import type { Macros, Micros } from '../domain/types';

/**
 * Extended food database for "Suchen" – generic foods the curated catalog
 * (data/foods.ts) does not have: fruit, vegetables, meat, fish, dairy,
 * grains, bread, legumes, nuts, drinks and a few convenience foods.
 *
 * Source: USDA FoodData Central, "SR Legacy" (April 2018) – public domain
 * (CC0 1.0). Values per 100 g as sold (raw unless the name says otherwise),
 * copied, not estimated; `fdc` is the FoodData Central id of every entry.
 * The German names are ours; the entry behind each name is chosen to match
 * (unfortified variants where the US fortifies, e.g. milk without added
 * vitamin D).
 *
 * - Energy is the source's value (food-specific factors, alcohol included) –
 *   not recomputed from the macros.
 * - A nutrient the source does not list is left out (unknown) – never 0.
 * - `enriched`: US flour products are enriched with iron, B vitamins (and
 *   often calcium). Those values would not match Swiss products, so they are
 *   left out for these entries – unknown instead of wrong.
 * - Salt follows from sodium (salt = sodium × 2.5) when the entry is used.
 *
 * This module is loaded on demand (services/foodDatabase.ts) – it is not
 * part of the main bundle.
 */
export type DbGroup = 'fruit' | 'vegetable' | 'grain' | 'snack' | 'meat' | 'fish' | 'dairy' | 'legume' | 'nut' | 'fat' | 'sweet' | 'drink' | 'convenience';

export interface DbFood {
  id: string;
  fdc: number;
  name: string;
  group: DbGroup;
  per100: Macros;
  micros: Micros;
  enriched?: true;
}

